use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let year = arr[0].as_i64().unwrap();
    let month = arr[1].as_i64().unwrap();
    let day = arr[2].as_i64().unwrap();

    let is_leap_year = |y: i64| (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let days_in_month = |y: i64, m: i64| match m {
        1 => 31, 2 => if is_leap_year(y) { 29 } else { 28 },
        3 => 31, 4 => 30, 5 => 31, 6 => 30,
        7 => 31, 8 => 31, 9 => 30, 10 => 31,
        11 => 30, 12 => 31, _ => 0,
    };

    let mut day_of_year = 0;
    for m in 1..month {
        day_of_year += days_in_month(year, m);
    }
    day_of_year += day;

    Value::from(day_of_year)
}
